/**
 * Pi extension: registers the `video` tool natively over the harness.
 * Generated by scripts/gen-surfaces.ts — do not edit.
 */

import { defaultDeps, handleVideoCall } from '@agent-video/cli'
import { Type } from '@sinclair/typebox'

type Text = { type: 'text'; text: string }
type Image = { type: 'image'; data: string; mimeType: string }
type Block = Text | Image

// minimal structural slice of pi's ExtensionAPI; no dependency on pi's packages just for a type
interface PiApi {
	registerTool(tool: {
		name: string
		label: string
		description: string
		parameters: ReturnType<typeof Type.Object>
		execute(
			toolCallId: string,
			params: Record<string, unknown>,
			signal: AbortSignal | undefined,
			onUpdate: ((update: { content: Block[] }) => void) | undefined
		): Promise<{ content: Block[]; isError?: boolean }>
	}): void
}

const parameters = Type.Object(
	{
		source: Type.String({ description: "Local video file path or URL. Call with only `source` first; the response tells you what to do next." }),
		from: Type.Optional(Type.Union([Type.String(), Type.Number()], { description: "Window start: seconds (83) or timestamp (\"1:23\", \"1:02:03\"). Omit to start from the beginning." })),
		until: Type.Optional(Type.Union([Type.String(), Type.Number()], { description: "Window end, same formats. Omit to go to the end of the video." })),
		look: Type.Optional(Type.Union([Type.Literal("overview"), Type.Literal("detailed"), Type.Literal("read_text"), Type.Literal("track_motion")], { description: "How to look: overview (fast triage), detailed (miss nothing), read_text (few large frames to read on-screen text/UI), track_motion (dense small frames for fast action). Subtitle text always rides along in metadata regardless; this only affects frame size/density. Omit for a balanced default." })),
		raw: Type.Optional(Type.String({ description: "Expert escape hatch: verbatim agent-video core CLI arguments starting with the subcommand, e.g. \"process --strategy keyframes --base-fps 0.2\". Mutually exclusive with from/until/look. Input/output plumbing is injected by the server." })),
		confirm: Type.Optional(Type.String({ description: "Echo a consent token issued by a previous response to authorize the pending action. Tokens are single-use and bound to the latest plan; pass confirm alone with source." })),
	},
	{ additionalProperties: false }
)

export default function (pi: PiApi) {
	const deps = defaultDeps()
	pi.registerTool({
		name: 'video',
		label: 'Video',
		description: "Watch a video (local path or URL) as VLM-readable frame grids with timestamps and subtitles. Call with just `source` first: short videos run immediately, everything else answers with metadata and copyable next calls.",
		parameters,
		async execute(_toolCallId, params, _signal, onUpdate) {
			const result = await handleVideoCall(params, deps, (_progress, _total, message) => {
				if (message !== undefined) onUpdate?.({ content: [{ type: 'text', text: message }] })
			})
			const content = result.content.filter((b): b is Block => b.type === 'text' || b.type === 'image')
			return { content, isError: result.isError === true }
		},
	})
}
